    h=len(grid); w=len(grid[0]); bg=grid[0][0]
    seen=[[False]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if seen[r][c] or grid[r][c]==bg: continue
            stack=[(r,c)]; seen[r][c]=True; cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and not seen[yy][xx] and grid[yy][xx]!=bg:
                        seen[yy][xx]=True; stack.append((yy,xx))
            rows={}
            for y,x in cells: rows.setdefault(y,[]).append(x)
            base_y=max(y for y in rows if any(grid[y][x]!=1 for x in rows[y]))
            base=next(grid[base_y][x] for x in rows[base_y] if grid[base_y][x]!=1)
            body_y=max(y for y in rows if y<base_y and len({grid[y][x] for x in rows[y]})==1)
            body=grid[body_y][rows[body_y][0]]
            while body_y-1 in rows and len({grid[body_y-1][x] for x in rows[body_y-1]})==1 and grid[body_y-1][rows[body_y-1][0]]==body:
                body_y-=1
            colors={grid[y][x] for y,x in cells if grid[y][x]!=1}
            core=next(iter(colors-{body,base}), body)
            if body==core:
                for y in rows:
                    if y>=body_y:
                        for x in rows[y]: out[y][x]=8
            else:
